-- GenDB engine variant Q04-wrapped_tables: template q04.sql, kind wrapped_tables (generated by generate.py; frozen)
SELECT
  o_orderpriority,
  COUNT(*) AS order_count
FROM (
  SELECT
    *
  FROM orders
) AS orders
WHERE
  o_orderdate >= $1
  AND o_orderdate < $1 + INTERVAL '3 MONTH'
  AND EXISTS(
    SELECT
      *
    FROM (
      SELECT
        *
      FROM lineitem
    ) AS lineitem
    WHERE
      l_orderkey = o_orderkey AND l_commitdate < l_receiptdate
  )
GROUP BY
  o_orderpriority
ORDER BY
  o_orderpriority
